				// Before record added
function BeforeAdd(&$values, &$sqlValues, &$message, $inline, $pageObject)
{

				date_default_timezone_set('Asia/Manila');
		$sql = "SELECT id
				  FROM scheduled_features
				  WHERE feature_name = 'scee_module_application'";

		$rs = DB::Query($sql);
		$data = $rs->fetchAssoc();

		if (!$data) {
			 $message = "Scheduled feature not found.";
			 return false;
		}

		$feature_id = $data["id"];
		$values["scheduled_feature_id"] = $feature_id;
		$values["created_at"] = now();
		$values["updated_at"] = now();
		$start = strtotime($values["start_datetime"]);
    $end   = strtotime($values["end_datetime"]);
		$termId   = isset($values["term_id"]) ? $values["term_id"] : null;

    // 1. Validation: Start must precede End
    if ($start >= $end) {
        $message = "The Start Date/Time must be earlier than the End Date/Time.";
        return false;
    }

    // 2. Validation: Prevent scheduling entirely in the past
    if ($end <= time()) {
        $message = "The End Date/Time cannot be set in the past.";
        return false;
    }

    // 3. Validation: Minimum Window Duration (e.g., 24 hours)
    //$min_duration_seconds = 24 * 60 * 60;
    //if (($end - $start) < $min_duration_seconds) {
    //    $message = "The evaluation period must span a minimum duration of 24 hours.";
    //    return false;
    //}

    // 4. Validation: Date Range Overlap Check
    // Standard Overlap Formula: (StartA <= EndB) AND (EndA >= StartB)
    $startDateStr = $values["start_datetime"];
    $endDateStr   = $values["end_datetime"];

    $sql = "SELECT id FROM scheduled_feature_dates 
            WHERE scheduled_feature_id = " . db_prepare_string($feature_id) . "
						 AND term_id = " . db_prepare_string($termId) . "
            AND (start_datetime <= " . db_prepare_string($endDateStr) . " 
                 AND end_datetime >= " . db_prepare_string($startDateStr) . ")";
    $rs = DB::Query($sql);
    if ($data = $rs->fetchAssoc()) {
        $message = "Schedule Conflict: An existing period for this feature overlaps with the selected date range.";
        return false;
    }

    return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record updated
function BeforeEdit(&$values, &$sqlValues, $where, &$oldvalues, &$keys, &$message, $inline, $pageObject)
{

		// Retrieve updated values if provided; otherwise fallback to stored values
    date_default_timezone_set('Asia/Manila');
		$values["created_at"] = now();
		$values["updated_at"] = now();
		$startStr = isset($values["start_datetime"]) ? $values["start_datetime"] : $oldvalues["start_datetime"];
    $endStr   = isset($values["end_datetime"])   ? $values["end_datetime"]   : $oldvalues["end_datetime"];
    $featId   = isset($values["scheduled_feature_id"])      ? $values["scheduled_feature_id"]      : $oldvalues["scheduled_feature_id"];
		$termId   = isset($values["term_id"]) ? $values["term_id"] : null;
    $start = strtotime($startStr);
    $end   = strtotime($endStr);
    $now   = time();

    // 1. Validation: Chronological order
    if ($start >= $end) {
        $message = "The Start Date/Time must be earlier than the End Date/Time.";
        return false;
    }

    // 2. Validation: Prevent modifying start date if the period has already commenced
    $oldStart = strtotime($oldvalues["start_datetime"]);
    if ($oldStart <= $now && $start != $oldStart) {
        $message = "This evaluation period has already commenced. You may only extend the End Date/Time.";
        return false;
    }

    // 3. Validation: Overlap detection excluding current record
    $recordId = $keys["id"]; // Replace with your primary key column name

    $sql = "SELECT id FROM scheduled_feature_dates 
            WHERE scheduled_feature_id = " . db_prepare_string($featId) . "
            AND id != " . intval($recordId) . "
						 AND term_id = " . db_prepare_string($termId) . "
            AND (start_datetime <= " . db_prepare_string($endStr) . " 
                 AND end_datetime >= " . db_prepare_string($startStr) . ")";

    $rs = DB::Query($sql);
    if ($data = $rs->fetchAssoc()) {
        $message = "Schedule Conflict: Another scheduled period overlaps with the specified date range.";
        return false;
    }

    return true;
;		
} // function BeforeEdit

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



